#!/usr/bin/env python3
import csv,json,math,sys
from pathlib import Path
r=Path(sys.argv[1]);p=json.loads((r/'origem.circuito').read_text(encoding='utf-8-sig'));c=p['Boards'][0]['Circuits'][0];binding=c['MotorStarterSelection'];rating=binding['Rating'];table=list(csv.DictReader((r/'tabela.csv').open(encoding='utf-8-sig'),delimiter=';'));row=next(x for x in table if x['Reference']==rating['Reference']);n=0
def check(ok):
 global n
 assert ok
 n+=1
check(p['FileVersion']==4 and 'motor-starter-assemblies-v1' in p['RequiredCapabilities']);check(binding['Engine']=='cs-partidas-conjuntos-v1');check(rating['Kind']==0 and row['Kind']=='ContactorOverload');check(rating['Poles']==binding['RequiredPoles']==3)
for key in ['Manufacturer','Reference','ControllerReference','Service','OverloadReference','TripClass','RequiredProtectionConfiguration','CoordinationType','AssemblyDocument','Source','DataVersion','Conditions']:check(rating[key]==row[key])
for key in ['VoltageV','FrequencyHz','RatedMotorA','ThermalMinimumA','ThermalMaximumA','ThermalSettingA','StandaloneBreakingKA','ConditionalKA','ControlVoltageV']:check(rating[key]==float(row[key]))
q=c.get('ReactiveKvarOverride');q=c['PowerKw']*math.tan(math.acos(c['PowerFactor'])) if q is None else q;nominal=1000*abs(complex(c['PowerKw'],q))/(math.sqrt(3)*c['Voltage']);demanded=nominal*c['DemandFactor'];iz=c['Cable']['AmpacityA']*c['Cable']['TemperatureFactor']*c['Cable']['GroupingFactor']*c['Cable']['Parallel']
check(math.isclose(nominal,20,rel_tol=1e-12));check(math.isclose(demanded,2,rel_tol=1e-12));check(rating['RatedMotorA']>=binding['MotorRatedA']>=nominal-1e-12);check(rating['ThermalMinimumA']<=rating['ThermalSettingA']<=rating['ThermalMaximumA']);check(rating['ThermalSettingA']==binding['MotorRatedA']==20);check(rating['ThermalSettingA']<=iz);check(rating['OverloadConnection']==1);check(rating['Service']==binding['RequiredService']);check(rating['TripClass']==binding['RequiredTripClass']);check(rating['CoordinationType']==binding['RequiredCoordinationType']);check(rating['ProtectionKind']==1 and row['ProtectionKind']=='PrimaryBreaker');check(c['BreakerA']>=binding['MotorRatedA']);check(c['Protection']['BreakingCapacityKA']>=p['Source']['ShortCircuitKA']);check(rating['ConditionalKA']>=p['Source']['ShortCircuitKA']);check(rating['StandaloneBreakingKA']==0);check(rating['ControlVoltageV']==binding['ControlVoltageV']==24);check(rating['ControlSupply']==binding['ControlSupply']==2);check(c['DemandFactor']==.1 and c['BreakerA']==25)
materials=list(csv.DictReader((r/'materiais.csv').open(encoding='utf-8-sig'),delimiter=';'));selected=[x for x in materials if x.get('Categoria')=='Conjunto de partida selecionado'];check(len(selected)==1 and selected[0]['Quantidade']=='1' and all(ref in selected[0]['Referência'] for ref in ['KM25-QA','OL20-QA']))
result={'status':'PASS','comparacoes':n,'motor_nominal_calculated_A':nominal,'network_demanded_A':demanded,'thermal_setting_A':rating['ThermalSettingA'],'controller_motor_limit_A':rating['RatedMotorA'],'scope':'Conjunto sintético: corrente nominal sem demanda, serviço/classe, associação declarada e materiais, sem homologação/partida dinâmica presumidas.'};(r/'verificacao-independente.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps(result,ensure_ascii=False,indent=2))
